package com.dsh.mobile.data

import java.security.cert.CertificateFactory
import java.security.cert.X509Certificate
import java.util.concurrent.atomic.AtomicReference
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import okhttp3.OkHttpClient
import org.junit.Assert.*
import org.junit.Test

/** Certificate vector generated by the plugin (dsh-remote-access createSelfSignedCertificate). */
class SecureChannelTest {
    private val vector = Json.parseToJsonElement(
        javaClass.getResourceAsStream("/secure-channel-vector.json")!!.bufferedReader().use { it.readText() }
    ).jsonObject
    private val certificate = CertificateFactory.getInstance("X.509")
        .generateCertificate(vector.getValue("cert").jsonPrimitive.content.byteInputStream()) as X509Certificate
    private val pin = vector.getValue("pin").jsonPrimitive.content

    @Test fun pinAndSafetyCodeMatchThePlugin() {
        assertEquals(pin, SecureChannel.pinOf(certificate))
        assertEquals(vector.getValue("safetyCode").jsonPrimitive.content, SecureChannel.safetyCode(pin))
        assertTrue(SecureChannel.isPin(pin))
        assertFalse(SecureChannel.isPin(pin.uppercase()))
        assertFalse(SecureChannel.isPin(pin.dropLast(1)))
    }

    @Test fun recordedPinAcceptsOnlyThatKey() {
        PinnedTrustManager(pin).checkServerTrusted(arrayOf(certificate), "ECDHE_ECDSA")
        val error = runCatching { PinnedTrustManager("0".repeat(64)).checkServerTrusted(arrayOf(certificate), "ECDHE_ECDSA") }.exceptionOrNull()
        assertTrue(error is ServerIdentityChangedException)
        assertTrue(error!!.message!!.contains(SecureChannel.safetyCode(pin)))
        assertTrue(runCatching { PinnedTrustManager(pin).checkServerTrusted(emptyArray(), "ECDHE_ECDSA") }.isFailure)
        assertTrue(runCatching { PinnedTrustManager(pin).checkClientTrusted(arrayOf(certificate), "ECDHE_ECDSA") }.isFailure)
    }

    @Test fun firstUseRecordsOneKeyAndRejectsAnyOtherLater() {
        val observed = AtomicReference<String?>(null)
        PinnedTrustManager(null, observed).checkServerTrusted(arrayOf(certificate), "ECDHE_ECDSA")
        assertEquals(pin, observed.get())
        PinnedTrustManager(null, observed).checkServerTrusted(arrayOf(certificate), "ECDHE_ECDSA")
        val other = AtomicReference<String?>("f".repeat(64))
        assertTrue(runCatching { PinnedTrustManager(null, other).checkServerTrusted(arrayOf(certificate), "ECDHE_ECDSA") }.exceptionOrNull() is ServerIdentityChangedException)
        // An explicit (QR) pin always wins over anything observed.
        assertTrue(runCatching { PinnedTrustManager("0".repeat(64), observed).checkServerTrusted(arrayOf(certificate), "ECDHE_ECDSA") }.isFailure)
    }

    @Test fun syntheticOriginIsStablePerTransportAndNeverARealHost() {
        val a = SecureChannel.syntheticHost("wss://relay.example.test/relay/v2/connect/" + "a".repeat(32))
        assertEquals(a, SecureChannel.syntheticHost("wss://relay.example.test/relay/v2/connect/" + "a".repeat(32)))
        assertNotEquals(a, SecureChannel.syntheticHost("wss://relay.example.test/relay/v2/connect/" + "b".repeat(32)))
        assertTrue(a.matches(Regex("[a-f0-9]{16}\\.e2e\\.dsh\\.invalid")))
    }

    @Test fun innerClientIsPinnedTls13Http11WithoutProxy() {
        val outer = OkHttpClient()
        val client = SecureChannel.client(outer, "ws://192.0.2.10:8787/api/remote-access/secure", pin, AtomicReference(null))
        assertEquals(listOf(okhttp3.Protocol.HTTP_1_1), client.protocols)
        assertEquals(java.net.Proxy.NO_PROXY, client.proxy)
        assertEquals(listOf(okhttp3.TlsVersion.TLS_1_3), client.connectionSpecs.single().tlsVersions)
        assertTrue(client.x509TrustManager is PinnedTrustManager)
        val host = SecureChannel.syntheticHost("ws://192.0.2.10:8787/api/remote-access/secure")
        assertEquals("127.0.0.1", client.dns.lookup(host).single().hostAddress)
        assertTrue(runCatching { client.dns.lookup("example.com") }.isFailure)
    }
}
